const listEl=document.getElementById('list');
const emptyEl=document.getElementById('empty');
const countEl=document.getElementById('count');
const msg=document.getElementById('msg');
const input=document.getElementById('newItem');
const aisleIn=document.getElementById('newAisle');
const dl=document.getElementById('aisles');
let items=[],revs={};
function say(t,bad){msg.textContent=t;msg.className=bad?'err':'muted';}
async function load(){
 try{
 const r=await tessera.call('data.read',{});
 items=r.data.items||[];revs=(r.revisions&&r.revisions.items)||{};
 render();
 }catch(e){say('Could not load the list.',true);}
}
function renderItem(it,ul){
 const li=document.createElement('li');
 if(it.done)li.className='done';
 const lab=document.createElement('label');
 const cb=document.createElement('input');
 cb.type='checkbox';cb.checked=!!it.done;
 const sp=document.createElement('span');sp.textContent=it.name;
 lab.append(cb,sp);
 cb.addEventListener('change',()=>toggle(it.id,cb.checked));
 const del=document.createElement('button');
 del.type='button';del.className='del';del.textContent='Remove';
 del.setAttribute('aria-label','Remove '+it.name);
 del.addEventListener('click',()=>remove(it.id));
 li.append(lab,del);ul.append(li);
}
function render(){
 listEl.textContent='';
 const groups=new Map();
 for(const it of items){
 const a=(it.aisle||'').trim();
 if(!groups.has(a))groups.set(a,[]);
 groups.get(a).push(it);
 }
 const names=[...groups.keys()].sort((x,y)=>{
 if(x===''&&y!=='')return 1;
 if(y===''&&x!=='')return -1;
 return x.localeCompare(y);
 });
 dl.textContent='';
 for(const n of names){
 if(n===''){continue;}
 const o=document.createElement('option');o.value=n;dl.append(o);
 }
 for(const n of names){
 const sec=document.createElement('section');
 const h=document.createElement('h2');h.textContent=n===''?'No aisle':n;
 const ul=document.createElement('ul');
 for(const it of groups.get(n))renderItem(it,ul);
 sec.append(h,ul);listEl.append(sec);
 }
 const left=items.filter(i=>!i.done).length;
 emptyEl.hidden=items.length>0;
 countEl.textContent=items.length?left+' of '+items.length+' still to get':'';
}
async function act(ops,okMsg){
 try{await tessera.call('data.patch',{operations:ops});say(okMsg,false);}
 catch(e){say('That change did not go through. Please try again.',true);}
 await load();
}
function toggle(id,v){act([{op:'replace',collection:'items',id,revisionCount:revs[id]||1,fields:{done:v}}],'');}
function remove(id){act([{op:'remove',collection:'items',id,revisionCount:revs[id]||1}],'Item removed.');}
document.getElementById('clearDone').addEventListener('click',()=>{
 const d=items.filter(i=>i.done);
 if(!d.length){say('No ticked items to remove.',false);return;}
 act(d.map(i=>({op:'remove',collection:'items',id:i.id,revisionCount:revs[i.id]||1})),d.length+' ticked item(s) removed.');
});
function add(){
 const n=input.value.trim();
 const a=aisleIn.value.trim();
 if(!n){say('Type an item name first.',true);input.focus();return;}
 input.value='';
 act([{op:'add',collection:'items',record:{name:n,done:false,aisle:a}}],n+' added.');
 input.focus();
}
document.getElementById('addBtn').addEventListener('click',add);
for(const f of [input,aisleIn]){
 f.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();add();}});
}
load();
